decolorize () 
{ 
    shopt -s extglob;
    echo "${1//+(\\033\[[0-1];3[0-7]m|\\033\[0m|[[:cntrl:]]\[[0-1];3[0-7]m|[[:cntrl:]]\[0m)/}";
    shopt -u extglob
}
colorize () 
{ 
    local color;
    color="${1}";
    shift;
    case "${color}" in 
        black)
            echo -e -n '\033[0;30m'
        ;;
        red)
            echo -e -n '\033[0;31m'
        ;;
        green)
            echo -e -n '\033[0;32m'
        ;;
        orange)
            echo -e -n '\033[0;33m'
        ;;
        blue)
            echo -e -n '\033[0;34m'
        ;;
        magenta)
            echo -e -n '\033[0;35m'
        ;;
        cyan)
            echo -e -n '\033[0;36m'
        ;;
        lightgray)
            echo -e -n '\033[0;37m'
        ;;
        darkgray)
            echo -e -n '\033[1;30m'
        ;;
        lightred)
            echo -e -n '\033[1;31m'
        ;;
        lightgreen)
            echo -e -n '\033[1;32m'
        ;;
        yellow)
            echo -e -n '\033[1;33m'
        ;;
        lightblue)
            echo -e -n '\033[1;34m'
        ;;
        lightmagenta)
            echo -e -n '\033[1;35m'
        ;;
        lightcyan)
            echo -e -n '\033[1;36m'
        ;;
        white)
            echo -e -n '\033[1;37m'
        ;;
        *)
            echo -e -n '\033[0m'
        ;;
    esac;
    echo -e -n "$@";
    echo -e -n '\033[0m'
}
center_string () 
{ 
    printf "%*s" $(( ( ${#1} + COLUMNS ) / 2 )) "${1}"
}
is_snapshot () 
{ 
    local snapshot;
    snapshot="${1}";
    if [ -z "${snapshot}" ]; then
        zerror "snapshot is undefined";
        return 1;
    fi;
    if [[ "${snapshot}" =~ @ ]]; then
        return 0;
    else
        return 1;
    fi
}
kcl_tokenize () 
{ 
    awk '
    BEGIN {
      strt = 1;
      quot = 0;
    }

    {
      for (i=1; i <= NF; i++) {
        # If an odd number of quotes are in this field, toggle quoting
        if ( gsub(/"/, "\"", $(i)) % 2 == 1 ) {
          quot = (quot + 1) % 2;
        }

        # Print a space if this is not the start of a line
        if (strt == 0) {
          printf " ";
        }

        printf "%s", $(i);

        if (quot == 0) {
          strt = 1;
          printf "\n";
        } else {
          strt = 0;
        }
      }
    }
  '
}
kcl_suppress () 
{ 
    local arg rem sup;
    while read -r arg; do
        sup=0;
        for rem in "$@";
        do
            if [[ "${arg}" == "${rem}" || "${arg%%=*}" == "${rem}" ]]; then
                sup=1;
                break;
            fi;
        done;
        [ "${sup}" -ne 1 ] && echo "${arg}";
    done
}
kcl_append () 
{ 
    local arg;
    cat;
    for arg in "$@";
    do
        [ -n "${arg}" ] && echo "$arg";
    done
}
kcl_assemble () 
{ 
    awk '
    BEGIN{ strt = 1; }

    {
      if (strt == 0) {
        printf " ";
      }

      printf "%s", $0;
      strt = 0;
    }
  '
}
zdebug () 
{ 
    [ "${loglevel:-4}" -ge 7 ] || return 1;
    local prefix trace last lines line lc i;
    lines="${1//[!'
']/}";
    lines="${#lines}";
    while IFS='
' read -r line; do
        if [ "${lc:=0}" -eq "${lines}" ]; then
            trace=;
            last=${#BASH_SOURCE[@]};
            for ((i=1 ; i<last ; i++ ))
            do
                trace="${FUNCNAME[$i]},${BASH_SOURCE[$i]},${BASH_LINENO[$i-1]}${trace:+;}${trace}";
            done;
            prefix="<7>ZBM:[$$]|${trace}|";
        else
            prefix="<7>ZBM:[$$]||";
        fi;
        lc=$(( lc + 1 ));
        echo "${prefix}${line}" > /dev/kmsg;
    done <<< "${1}"
}
zinfo () 
{ 
    [ "${loglevel:-4}" -ge 6 ] || return 1;
    echo "<6>ZFSBootMenu: $1" > /dev/kmsg
}
znotice () 
{ 
    [ "${loglevel:-4}" -ge 5 ] || return 1;
    echo "<5>ZFSBootMenu: $1" > /dev/kmsg
}
zwarn () 
{ 
    [ "${loglevel:-4}" -ge 4 ] || return 1;
    : > "${BASE}/have_warnings";
    echo "<4>ZFSBootMenu: $1" > /dev/kmsg
}
zerror () 
{ 
    [ "${loglevel:-4}" -ge 3 ] || return 1;
    : > "${BASE}/have_errors";
    echo "<3>ZFSBootMenu: $1" > /dev/kmsg
}
